    extraIncome: 'Tăng thêm thu nhập',
    extraIncomeDesc: 'Tận dụng thời gian rảnh để tạo thêm nguồn thu nhập thông qua việc hỗ trợ mua sắm, giao nhu yếu phẩm và phục vụ nhu cầu của khách hàng trong khu vực.',
    support247: 'Hỗ trợ 24/7',
    support247Desc: 'Đội ngũ Biteo luôn sẵn sàng hỗ trợ bạn mọi lúc mọi nơi qua hotline và chat.',
    flexibleWork: 'Làm việc linh hoạt',
    flexibleWorkDesc: 'Bạn tự chủ thời gian và khu vực hoạt động, có thể sắp xếp công việc theo lịch trình cá nhân. Không bị bó buộc bởi khung giờ cố định, bạn chủ động lựa chọn thời điểm phù hợp để nhận và hỗ trợ các đơn hàng.',
    opportunityForYou: 'Cơ hội dành cho bạn',
    opportunityForYouDesc: 'Biteo kết nối bạn với nhu cầu mua sắm thực tế của người dùng trong khu vực, giúp biến thời gian rảnh thành cơ hội tạo thêm thu nhập. Dù bạn đang làm công việc khác, kinh doanh cá nhân hay muốn tìm một công việc linh hoạt, Biteo đều mang đến một lựa chọn phù hợp.',
    workInYourArea: 'Làm việc ngay tại khu vực của bạn',
    workInYourAreaDesc: 'Bạn có thể hoạt động tại khu vực mình am hiểu, thuận tiện di chuyển và dễ dàng nắm bắt nhu cầu mua sắm thực tế của người dân địa phương.',
    supportedByBiteo: 'Được Biteo đồng hành',
    supportedByBiteoDesc: 'Trong quá trình hoạt động, bạn luôn có đội ngũ Biteo hỗ trợ 24/7 thông qua hotline và chat, sẵn sàng giải đáp các vấn đề phát sinh và hỗ trợ bạn khi cần.',
    buildLocalEcosystem: 'Cùng Biteo xây dựng hệ sinh thái địa phương',
    buildLocalEcosystemDesc: 'Mỗi đơn hàng không chỉ là một lần mua sắm, mà còn là một cách kết nối người dân với chợ, cửa hàng và dịch vụ trong khu vực. Khi trở thành nhân viên đi chợ hộ Biteo, bạn đang góp phần xây dựng một hệ sinh thái mua sắm tiện lợi, hiện đại và gần gũi hơn với cộng đồng.',
