    ctvHeroTitle: 'Trở thành CTV của Biteo ngay hôm nay',
    ctvHeroDesc: 'Bạn đang tìm kiếm một công việc linh hoạt, không cần vốn và có thể chủ động thời gian? Trở thành Cộng tác viên Biteo là cơ hội để bạn tận dụng thời gian rảnh, giới thiệu các dịch vụ của Biteo đến khách hàng và tạo thêm nguồn thu nhập. Dù bạn là sinh viên, nhân viên văn phòng, người kinh doanh tự do hay đang muốn tìm một công việc làm thêm, Biteo đồng hành cùng bạn từ những bước đầu tiên với hệ thống hỗ trợ, đào tạo và lộ trình phát triển rõ ràng.',
