    flexibleWork: 'Flexible Work',
    flexibleWorkDesc: 'You have control over your time and service area, allowing you to organize your work around your personal schedule. Free from fixed working hours, you can choose the best times to accept and fulfill orders.',
    opportunityForYou: 'An Opportunity for You',
    opportunityForYouDesc: 'Biteo connects you with real shopping needs from users in your area, helping you turn your free time into an opportunity to earn extra income. Whether you already have another job, run your own business, or are looking for flexible work, Biteo offers an option that fits your needs.',
    workInYourArea: 'Work Right in Your Local Area',
