    supportedByBiteo: 'Supported by Biteo',
    supportedByBiteoDesc: 'Throughout your journey, the Biteo team is available 24/7 via hotline and chat, ready to answer your questions, resolve any issues, and provide support whenever you need it.',
    buildLocalEcosystem: 'Build the Local Ecosystem with Biteo',
    buildLocalEcosystemDesc: 'Every order is more than just a shopping trip — it is a way to connect people with local markets, stores, and services in their area. By becoming a Biteo personal shopper, you are helping build a more convenient, modern, and community-focused local shopping ecosystem.',
    becomeBiteoShopper: 'Become a Biteo Personal Shopper',
