    registerAsBiteoPartner: 'Become a Biteo Partner',
    registerAsBiteoPartnerDesc: 'With just a smartphone, you can get started anytime, anywhere. No upfront investment, no inventory to manage, and no physical location required. Biteo provides the platform and guidance you need to get familiar with the work and start with ease.',


